export default {"html":"<p data-line=\"0\" class=\"code-line\">This article is part of the <a href=\"https://adventar.org/calendars/5963\" target=\"_blank\" rel=\"noopener noreferrer\">Ionic Framework / Capacitor Advent Calendar 2020</a>.</p>\n<hr data-line=\"2\" class=\"code-line\">\n<p data-line=\"4\" class=\"code-line\">I often build projects with Ionic/Angular on the frontend and NestJS + MySQL on the backend. After six months, package versions climb and default project layouts shift, so I scaffold with a simple monorepo template.</p>\n<hr data-line=\"6\" class=\"code-line\">\n<h2 id=\"setup-steps\" data-line=\"8\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#setup-steps\" aria-hidden=\"true\"></a> <a href=\"#%E5%B0%8E%E5%85%A5%E6%89%8B%E9%A0%86\"></a>Setup Steps</h2>\n<ol start=\"0\" data-line=\"10\" class=\"code-line\">\n<li data-line=\"10\" class=\"code-line\">Keep CLI versions up to date</li>\n</ol>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"12\"><span class=\"line\"><span>% npm i @ionic/cli@latest @nestjs/cli@latest -g</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><ol data-line=\"17\" class=\"code-line\">\n<li data-line=\"17\" class=\"code-line\">Clone the template</li>\n</ol>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"19\"><span class=\"line\"><span>% git clone git@github.com:rdlabo-team/create-ionic-nest-app.git your-project-name</span></span>\n<span class=\"line\"><span>% cd your-project-name</span></span>\n<span class=\"line\"><span>% git remote set-url origin git@github.com:your-account/your-repository.git</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><ol start=\"2\" data-line=\"26\" class=\"code-line\">\n<li data-line=\"26\" class=\"code-line\">Create the Ionic app</li>\n</ol>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"28\"><span class=\"line\"><span>% npm run create:app</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><ol start=\"3\" data-line=\"33\" class=\"code-line\">\n<li data-line=\"33\" class=\"code-line\">Create the NestJS app</li>\n</ol>\n<p data-line=\"35\" class=\"code-line\">If you host somewhere other than Lambda, run:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"37\"><span class=\"line\"><span>% npm run create:api</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"42\" class=\"code-line\">For Lambda hosting, use this instead—a Serverless Framework layout:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"44\"><span class=\"line\"><span>% npm run create:api:sls</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><ol start=\"4\" data-line=\"49\" class=\"code-line\">\n<li data-line=\"49\" class=\"code-line\">Link with lerna</li>\n</ol>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"51\"><span class=\"line\"><span>% npm run install</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><h2 id=\"releasing\" data-line=\"56\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#releasing\" aria-hidden=\"true\"></a> <a href=\"#%E3%83%AA%E3%83%AA%E3%83%BC%E3%82%B9%E3%81%99%E3%82%8B%E6%99%82\"></a>Releasing</h2>\n<p data-line=\"58\" class=\"code-line\">There is no GitHub Actions template bundled, but I recommend releasing with:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"60\"><span class=\"line\"><span>% npm run release</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"65\" class=\"code-line\"><a href=\"https://zenn.dev/rdlabo/articles/1fda37f6e1025999e86e\" target=\"_blank\" rel=\"noopener noreferrer\">https://zenn.dev/rdlabo/articles/1fda37f6e1025999e86e</a> may be a useful reference.</p>\n<h2 id=\"what-is-included\" data-line=\"67\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#what-is-included\" aria-hidden=\"true\"></a> <a href=\"#%E4%BD%95%E3%81%8C%E7%94%A8%E6%84%8F%E3%81%95%E3%82%8C%E3%81%A6%E3%82%8B%E3%81%8B\"></a>What Is Included</h2>\n<ul data-line=\"69\" class=\"code-line\">\n<li data-line=\"69\" class=\"code-line\">Prettier formatting on pre-commit, configured from the start</li>\n</ul>\n<hr data-line=\"71\" class=\"code-line\">\n<p data-line=\"73\" class=\"code-line\">I hope this makes it easy to start an Ionic project with an API server. See you next time.</p>\n","headings":[{"id":"setup-steps","text":"Setup Steps","level":2},{"id":"releasing","text":"Releasing","level":2},{"id":"what-is-included","text":"What Is Included","level":2}]} as const;
